  "plans.title": "قارن بين خطط StockHaven",
  "plans.intro": "حساب واحد، أيًا كانت الخطة التي تختارها — تغطي خطة Business ما يصل إلى خمسة أعمال. الأسعار شهرية بالدولار الأمريكي، ويمكن للعملاء الجدد المؤهلين على الموقع الإلكتروني الحصول على تجربة واحدة لمدة سبعة أيام عبر Essentials وBusiness. لا تؤدي الترقية من اشتراك Essentials الحالي إلى Business إلى إعادة بدء التجربة أو إنشاء تجربة مجانية أخرى. أسعار خطط الموقع الإلكتروني قبل الضرائب السارية، إن وجدت. سيظهر مبلغ الخصم الدقيق قبل أن توافق على الاشتراك.",
