  "exports.eyebrow": "البيانات",
  "exports.title": "التصدير والنسخ الاحتياطية",
  "exports.subtitleStart": "التنزيلات تقتصر دائمًا على",
  "exports.subtitleRest": ". ويُسمَّى كل ملف باسم النشاط التجاري وتاريخ إنشائه.",
  "exports.createBusinessFirst": "أنشئ نشاطًا تجاريًا أولًا — فالتصدير يخص نشاطًا تجاريًا، لا التطبيق.",
  "exports.lockedTitle": "تصدير CSV وExcel ميزة في خطة Business",
  "exports.lockedDesc": "مساحة عملك على خطة Essentials. تضيف خطة Business تصدير CSV وExcel، وتقييم المخزون، ومنتجات وموظفين بلا حدود، والمورّدين، والمشتريات، والحزم.",
  "exports.seeBusiness": "اطّلع على ما تتضمنه خطة Business",
  "exports.whatTheseAre": "ما هذه الملفات",
  "exports.about1": "تأتي كل مجموعة بيانات بصيغة CSV أو مصنف Excel حقيقي (.xlsx) — أما مصنف المخزون الكامل فهو بصيغة Excel فقط، مع ورقة لكل مجموعة بيانات. تُفتح ملفات CSV في Excel وNumbers وGoogle Sheets ومعظم تطبيقات المخزون. تُحفظ نصوص UTF-8، والفواصل المقتبسة، وفواصل الأسطر في الملاحظات، والأصفار البادئة في الرموز، وتُعطَّل الخلايا التي تبدأ كصيغة لتفتحها جداول البيانات كنص.",
  "exports.about2": "في ملفات Excel، تكون رموز SKU وUPC وISBN والرموز الشريطية خلايا نصية — فلا تظهر أبدًا بالتدوين العلمي ولا تُحذف أصفارها — مع ضبط عرض الأعمدة وعوامل تصفية الرؤوس وتنسيقات العملة أو الكمية. ويُبقي مصنف المخزون الكامل المنتجات ومستويات المخزون والمواقع والحركات في أوراق منفصلة.",
  "exports.about3": "تتوقف عمليات التصدير الكبيرة جدًا عند 20,000 صف لكل مجموعة بيانات — وعند حدوث ذلك يذكر اسم الملف ذلك (truncated-20000)، حتى لا يبدو ملف جزئي مكتملًا أبدًا.",
  "exports.about4": "النسخة الاحتياطية لقطة لبياناتك، وليست استعادة بنقرة واحدة. استعادتها عمل يدوي يبدأ بالمراجعة، فاحتفظ بالملف في مكان آمن — فلا شيء في التطبيق يستطيع إعادة إنشاء نشاط تجاري محذوف منه بعد. وتُدار نسخ رمز التطبيق ومنصة Base44 الاحتياطية بشكل منفصل عن هذه الملفات.",
  "exports.about5": "تُدرج الصور والمرفقات كروابطها المخزنة — فملفات الصور نفسها لا تُضمَّن في التنزيل.",
  "exports.backupTitle": "نسخة احتياطية كاملة",
  "exports.backupDesc": "ملف واحد يحتوي على منتجات هذا النشاط التجاري، ومواقعه، ومستويات مخزونه، وسجل حركاته الكامل، ومورّديه، ومشترياته، وطلباته، ومرتجعاته، وعمليات جرده، وقوائمه — بالإضافة إلى إعدادات ملفه الشخصي. احتفظ به في مكان تتحكم فيه.",
  "exports.backupIncludes1": "المنتجات والرموز والتكاليف والملاحظات",
  "exports.backupIncludes2": "المواقع والكميات لكل موقع",
