  "import.createDesc": "تضيف الصفوف غير الموجودة في الكتالوج بعد. وتُتخطى رموز SKU والرموز الشريطية المكررة المستخدمة بالفعل، ويمكن أن يصل المخزون الافتتاحي إلى موقع تختاره كاستلام.",
  "import.updateTitle": "تحديث المنتجات الحالية",
  "import.updateDesc": "يطابق كل صف حسب SKU أو معرّف السجل ويعرض القيمة القديمة بجانب القيمة الجديدة المقترحة. وتترك الخلايا الفارغة القيمة المحفوظة كما هي ما لم تطلب مسح الفراغات، ولا تُمس الكميات أبدًا.",
  "import.receiveModeTitle": "استلام المخزون",
  "import.receiveModeDesc": "يضيف الكميات الواصلة إلى موقع واحد ويكتب استلامًا في سجل الحركات لكل سطر. وتُعلَّم كل دفعة، حتى لا يمكن استلام الورقة نفسها مرتين.",
  "import.excelNote": "تُقرأ مصنفات Excel (.xlsx) مباشرة — اختر ورقة العمل وتُطابَق الأعمدة لك. وتبقى الرموز كاملة: فالرمز UPC المحفوظ كنص يحتفظ بأرقامه وأصفاره البادئة. وتُدرج الصفوف التي لا يمكن استيرادها مع سبب",
