  "print.supplierBlockedDesc": "تأتي مستندات المورّدين مع خطة Business — المورّدون والمشتريات وأوامر الشراء. وكل ما لديك الآن يستمر في العمل.",
  "print.seeBusiness": "اطّلع على ما تتضمنه خطة Business",
  "print.nothingToPrint": "لا شيء لطباعته بعد",
  "print.pickOrderHint": "اختر أمر شراء من القائمة لمعاينة المستند.",
  "print.pickCustomerOrderHint": "اختر طلب عميل من القائمة لمعاينة المستند.",
  "print.pickReturnHint": "اختر مرتجعًا مسجلًا من القائمة لمعاينة المستند.",
  "print.chooseStyleHint": "اختر أسلوبًا، ثم اختر منتجات من القائمة. وتُظهر المعاينة بالضبط ما يخرج من الطابعة.",
  "print.howToReach": "كيف تصل إلى طابعتك",
  "print.howIntro": "يتصل هذا التطبيق بالطابعات التي تملكها بالفعل — فهو ليس طابعة بحد ذاته. وهناك أربع طرق للوصول إلى واحدة، وتُطبع الملصقات على الخطتين عبر أي منها. أما قوائم التعبئة وأوامر الشراء ومستندات المورّدين والتقارير فهي خاصة بخطة Business فقط، أيًا كان الاتصال.",
  "print.howBluetoothLead": "Bluetooth.",
  "print.howBluetoothBody": "من هذه الصفحة، على Chrome أو Edge لسطح المكتب وعلى Chrome لنظام Android: اختر طابعة الملصقات وستذهب الملصقات إليها مباشرة. ولا يعمل ذلك في Safari على iOS — فعلى iPhone، تأتي الطباعة عبر Bluetooth مع تطبيق الجوال بدلًا من ذلك. والطابعة التي تتحدث لغة Zebra ZPL فقط أو لغة Brother الخاصة لن تفهم الملصقات التي ترسلها هذه الصفحة؛ ويُتحقق من ذلك مقابل طابعات حقيقية قبل اعتباره يعمل.",
  "print.howWifiLead": "Wi-Fi.",
  "print.howWifiBody": "ثبّت الطابعة على شبكة Wi-Fi الخاصة بمتجرك، ثم استخدم زر الطباعة — فهي تطبع عبر الطابعة المثبتة على هذا الكمبيوتر، عبر شبكة المتجر. وعلى iPhone، تأتي AirPrint مدمجة: فطابعة AirPrint على شبكة Wi-Fi نفسها تظهر ببساطة في ورقة الطباعة، بلا سلك وبلا تطبيق، ولا يحتاج التطبيق إلى رمز خاص بـ AirPrint. ويجب أن تدعم الطابعة AirPrint (معظم الطابعات الجديدة تدعمها) وأن يكون الهاتف والطابعة على شبكة Wi-Fi نفسها.",
  "print.howEthernetLead": "Ethernet.",
  "print.howEthernetBody": "صِل الطابعة بشبكة متجرك بسلك Ethernet، وثبّتها على الكمبيوتر، واطبع عبر زر الطباعة. وEthernet مسار لسطح المكتب والكمبيوتر — فأجهزة iPhone لا تستخدم أسلاك Ethernet.",
  "print.howUsbLead": "USB.",
  "print.howUsbBody": "صِل الطابعة بالكمبيوتر بسلكها واستخدم زر الطباعة — فهي تطبع عبر الطابعة المثبتة هناك. وعلى هاتف Android مع كابل USB OTG، يتحدث زر USB أعلاه مباشرة مع الطابعة. ولا تستطيع أجهزة iPhone الطباعة عبر USB مباشرة — فلا يوجد WebUSB هناك — لذا استخدم Wi-Fi / AirPrint، أو Bluetooth من تطبيق الجوال.",
  "print.howCordsLead": "الأسلاك لا تزال تخدم أجهزة iPhone، بخطوة واحدة إضافية.",
  "print.howCordsBody": "طابعة USB موصولة بكمبيوتر المتجر، أو طابعة Ethernet موصولة بالشبكة، تظهر على iPhone عبر شبكة Wi-Fi الخاصة بالمتجر (AirPrint / طابعة مشتركة) — فالأسلاك تضع الطابعة على الشبكة بثبات، ويصل إليها الهاتف لاسلكيًا.",
  "print.howOfflineLead": "إذا انقطع الإنترنت،",
