  "settings.title": "الإعدادات",
  "settings.trial.cancelKeeps": "الإلغاء أثناء فترتك التجريبية يُبقي لك 7 أيام كاملة — ينتهي الوصول في {date}، ولن تُخصم منك أي رسوم.",
  "staff.access.noSeatBody": "ليس لحسابك مقعد موظفين في هذا العمل، لذا يبقى مخزونه مغلقًا. اطلب من المالك إضافتك في «الموظفون والأدوار».",
  "staff.access.noSeatTitle": "هذا العمل غير مفتوح لتسجيل دخولك",
  "staff.access.pendingBody": "لدى هذا العمل دعوة لبريدك الإلكتروني لم تُفعَّل بعد. اطلب من المالك تعيين حالة موظفيك إلى نشطة. ولن يظهر أي شيء هنا حتى ذلك الحين.",
  "staff.access.pendingTitle": "دعوتك غير نشطة بعد",
  "staff.access.signOut": "تسجيل الخروج",
  "staff.access.suspendedBody": "أوقف مسؤول حساب الموظفين هذا للعمل النشط. اطلب منه إعادتك إلى نشط، ثم سجّل الدخول مجددًا.",
  "staff.access.suspendedTitle": "وصولك متوقف مؤقتًا",
  "staff.addFirst": "أضف أول موظف",
  "staff.addMember": "إضافة موظف",
  "staff.emptyBody": "أضف شخصًا، ومنحه دورًا والأذونات التي تترتب عليه، وستُرسل إليه دعوة بالبريد الإلكتروني لتسجيل الدخول إلى هذا العمل.",
  "staff.emptyTitle": "لا يوجد موظفون بعد",
  "staff.eyebrow": "الفريق",
  "staff.how.p1": "لكل عضو دور وقائمة أذونات خاصة به، لذا يمكنك البدء من دور وتغيير شيء واحد دون إنشاء دور جديد. وتحرير دور لا يعيد كتابة الأعضاء الموجودين عليه — افتح عضوًا لإعادة تطبيق الإعدادات الافتراضية لدوره.",
  "staff.how.p2": "الأدوار المخصصة ميزة من مزايا خطة Business: تستخدم خطة Essentials الأدوار الخمسة المدمجة (المالك، المدير، أمين المخزون، موظف المبيعات، المشاهِد).",
  "staff.how.p3": "تُرسل الدعوات بالبريد الإلكتروني. ولا يمكن للعضو تسجيل الدخول إلا بعد قبوله، وإزالة شخص من هذه القائمة لا تحذف حسابه في التطبيق.",
  "staff.how.p4": "المتجر هو الموقع المُسند إلى الشخص. ويُسجَّل على بطاقته؛ أما ما يمكنه فتحه فيتحدد بدوره وأذوناته.",
  "staff.how.p5": "تحدد الأذونات ما يمكن لكل شخص فتحه: تُخفى عناصر القائمة الخارجة عن دوره، ويظهر عنوان محظور إشعار «ليس ضمن دورك» بدلًا من الصفحة. ويسري أي تغيير في المرة التالية التي يحمّل فيها ذلك الشخص التطبيق؛ وإيقاف عضو يمنعه من الدخول تمامًا.",
  "staff.how.p6": "يمكن للمسؤولين رؤية كل البيانات وتغييرها، وإدارة مستخدمي التطبيق والأدوار، ولا يقيّدهم أي دور موظفين أبدًا. ومن ليس لديه سجل موظفين — مالك عمل جديد — يحتفظ بوصول كامل.",
  "staff.howTitle": "كيف يعمل الموظفون والأدوار",
